#Generated by ChatGPT

import numpy as np
import pytest
import torch

from vision_core.detection.detector import YOLODetector


class FakeBoxes:
    def __init__(self):
        self.xyxy = torch.tensor([
            [10.0, 20.0, 100.0, 200.0]
        ])

        self.cls = torch.tensor([0])

        self.conf = torch.tensor([0.91])


class FakeResult:
    def __init__(self):
        self.boxes = FakeBoxes()
        self.names = {
            0: "defect"
        }


class FakeModel:
    def predict(self, frame, conf, device):
        return [FakeResult()]


def test_predict_returns_detection():

    detector = YOLODetector(
        model=FakeModel(),
        confidence_threshold=0.5,
        device="cpu"
    )

    frame = np.zeros(
        (640, 640, 3),
        dtype=np.uint8
    )

    detections = detector.predict(frame)

    assert len(detections) == 1

    detection = detections[0]

    assert detection.bbox == [10.0, 20.0, 100.0, 200.0]
    assert detection.class_id == 0
    assert detection.class_name == "defect"
    assert detection.confidence == pytest.approx(0.91)


def test_predict_none_frame():

    detector = YOLODetector(
        model=FakeModel(),
        confidence_threshold=0.5,
        device="cpu"
    )

    with pytest.raises(ValueError):
        detector.predict(None)


class EmptyModel:

    def predict(self, frame, conf, device):
        result = FakeResult()
        result.boxes.xyxy = torch.empty((0, 4))
        result.boxes.cls = torch.empty((0,))
        result.boxes.conf = torch.empty((0,))

        return [result]


def test_predict_no_detections():

    detector = YOLODetector(
        model=EmptyModel(),
        confidence_threshold=0.5,
        device="cpu"
    )

    frame = np.zeros(
        (640, 640, 3),
        dtype=np.uint8
    )

    detections = detector.predict(frame)

    assert detections == []


class FailingModel:

    def predict(self, frame, conf, device):
        raise RuntimeError("Model failed")


def test_predict_model_failure():

    detector = YOLODetector(
        model=FailingModel(),
        confidence_threshold=0.5,
        device="cpu"
    )

    frame = np.zeros(
        (640, 640, 3),
        dtype=np.uint8
    )

    with pytest.raises(RuntimeError, match="YOLO inference failed"):
        detector.predict(frame)